"use client";

import * as React from "react";
import styles from "../styles/meteors.module.css";

export interface MeteorsProps {
  /** Number of meteors in the shower */
  count?: number;
  /** Speed multiplier (1 = base 2–5s fall per meteor) */
  speed?: number;
  /** Travel direction in degrees, clockwise from pointing right (135 = down-left) */
  angle?: number;
  /** Meteor head and trail color */
  meteorColor?: string;
  /** Foreground content rendered above the shower */
  children?: React.ReactNode;
  /** Optional className merged onto the root */
  className?: string;
}

const rand = (n: number) => {
  const x = Math.sin(n * 9301 + 49297) * 233280;
  return x - Math.floor(x);
};

export function Meteors({
  count = 14,
  speed = 1,
  angle = 135,
  meteorColor = "#38bdf8",
  children,
  className = "",
}: MeteorsProps) {
  const safeSpeed = speed > 0 ? speed : 1;
  const total = Math.max(0, Math.round(count));
  const styleVars = {
    "--mf-mt-color": meteorColor,
    "--mf-mt-angle": `${angle}deg`,
  } as React.CSSProperties;

  return (
    <div style={styleVars} className={`${styles.root} ${className}`.trim()}>
      <div aria-hidden="true" className={styles.sky}>
        {Array.from({ length: total }, (_, i) => (
          <span
            key={i}
            className={styles.meteor}
            style={{
              left: `${(rand(i) * 130 - 10).toFixed(2)}%`,
              top: `${(rand(i + 7) * 50 - 15).toFixed(2)}%`,
              animationDuration: `${((2 + rand(i + 1) * 3) / safeSpeed).toFixed(2)}s`,
              animationDelay: `-${(rand(i + 2) * 5).toFixed(2)}s`,
            }}
          />
        ))}
      </div>
      <div className={styles.content}>
        {children ?? (
          <div className={styles.copy}>
            <h3 className={styles.title}>Meteor Shower</h3>
            <p className={styles.subtitle}>Pure CSS streaks with deterministic timing.</p>
          </div>
        )}
      </div>
    </div>
  );
}

.root {
  position: relative;
  overflow: hidden;
  display: flex;
  width: 100%;
  min-height: 18rem;
  border-radius: 1rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background: radial-gradient(ellipse at 50% 0%, var(--mf-surface-raised, #1b1b22) 0%, var(--mf-surface, #121218) 45%, var(--mf-bg, #09090b) 100%);
  color: var(--mf-fg, #f4f4f6);
}

.sky {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.meteor {
  position: absolute;
  width: 6rem;
  height: 1px;
  border-radius: 999px;
  background: linear-gradient(to left, var(--mf-mt-color, var(--mf-accent, #38bdf8)), transparent);
  transform-origin: right center;
  transform: rotate(var(--mf-mt-angle, 135deg)) translateX(0);
  opacity: 0;
  animation-name: mfMeteorFall;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  will-change: transform, opacity;
}

.meteor::after {
  content: "";
  position: absolute;
  right: -1px;
  top: 50%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  transform: translateY(-50%);
  background-color: var(--mf-fg, #f4f4f6);
  box-shadow: 0 0 6px 2px var(--mf-mt-color, var(--mf-accent, #38bdf8));
}

.content {
  position: relative;
  z-index: 1;
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.copy {
  text-align: center;
}

.title {
  margin: 0;
  font-size: 1.75rem;
  font-weight: 600;
  letter-spacing: -0.03em;
}

.subtitle {
  margin: 0.5rem 0 0;
  font-size: 0.875rem;
  color: var(--mf-muted, #a1a1aa);
}

@keyframes mfMeteorFall {
  0% {
    transform: rotate(var(--mf-mt-angle, 135deg)) translateX(0);
    opacity: 0;
  }
  6% {
    opacity: 1;
  }
  70% {
    opacity: 1;
  }
  100% {
    transform: rotate(var(--mf-mt-angle, 135deg)) translateX(40rem);
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .meteor {
    animation: none;
    opacity: 0.5;
  }
}

