"use client";

import { motion } from "motion/react";

const rand = (n: number) => { const x = Math.sin(n * 9301 + 49297) * 233280; return x - Math.floor(x); };

export function MeteorsTailwind({ count = 14 }) {
  return (
    <div className="relative flex min-h-72 w-full items-center justify-center overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-950">
      {Array.from({ length: count }, (_, i) => (
        <motion.span
          key={i}
          aria-hidden
          className="absolute h-px w-24 bg-gradient-to-r from-sky-400 to-transparent"
          style={{ left: `${rand(i) * 120}%`, top: "-10%", rotate: -45 }}
          animate={{ x: [0, -500], y: [0, 500], opacity: [1, 1, 0] }}
          transition={{ duration: 2 + rand(i + 1) * 3, repeat: Infinity, delay: rand(i + 2) * 5, ease: "linear" }}
        />
      ))}
      <h3 className="relative z-10 text-2xl font-semibold text-zinc-100">Meteor Shower</h3>
    </div>
  );
}
